import asyncio, time

@app.get("/report")
def report():  # plain def -> threadpool
    time.sleep(1)  # OK here
    return {"ready": True}

@app.get("/ping")
async def ping():  # async def -> event loop
    await asyncio.sleep(1)  # never time.sleep here!
    return {"pong": True}

import httpx

@app.get("/trip/{city}")
async def trip(city: str):
    async with httpx.AsyncClient() as client:
        r = await client.get(f"https://weather.example.com/{city}")
    return {"city": city, "temp": r.json()["temp"]}

from fastapi import FastAPI, WebSocket, WebSocketDisconnect
app = FastAPI()

@app.websocket("/ws")
async def echo(websocket: WebSocket):
    await websocket.accept()
    try:
        while True:
            text = await websocket.receive_text()
            await websocket.send_text(f"You said: {text}")
    except WebSocketDisconnect:
        print("client left")

class ConnectionManager:
    def __init__(self):
        self.active: list[WebSocket] = []
    async def connect(self, ws: WebSocket):
        await ws.accept()
        self.active.append(ws)
    def disconnect(self, ws: WebSocket):
        self.active.remove(ws)
    async def broadcast(self, msg: str):
        for ws in self.active:
            await ws.send_text(msg)
manager = ConnectionManager()

@app.websocket("/ws/{name}")
async def chat(websocket: WebSocket, name: str):
    await manager.connect(websocket)
    try:
        while True:
            text = await websocket.receive_text()
            await manager.broadcast(f"{name}: {text}")
    except WebSocketDisconnect:
        manager.disconnect(websocket)
        await manager.broadcast(f"{name} left")

